<script setup lang="ts">
import {useTableWidths as useListTableWidths} from './tableWidths'
const listWidths=useListTableWidths('ListingSyncDialogLists')

import {ref,reactive,watch,onUnmounted} from 'vue'
import {api} from './session'
import {ElMessage} from 'element-plus'
const props=defineProps<{open:boolean,store?:string,market?:string}>(),emit=defineEmits(['close','updated'])
const options=ref<any>({stores:[],markets:[]}),jobs=ref<any[]>([]),form=reactive({stores:[] as string[],markets:[] as string[]}),busy=ref(false),error=ref('');let timer:ReturnType<typeof setInterval>|undefined
async function load(){try{jobs.value=await api('/listing-sync')}catch(e){error.value=(e as Error).message}}
watch(()=>props.open,async v=>{clearInterval(timer);if(v){try{options.value=await api('/options');form.stores=props.store?[props.store]:[];form.markets=props.market?[props.market]:options.value.markets;await load();timer=setInterval(load,5000)}catch(e){error.value=(e as Error).message}}else emit('updated')});onUnmounted(()=>clearInterval(timer))
async function sync(){busy.value=true;error.value='';try{await api('/listing-sync',form);ElMessage.success('Listing 同步已加入后台队列');await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
</script>
<template><el-dialog :model-value="open" title="同步 Listing" width="800px" @close="emit('close')"><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-form label-position="top"><el-form-item label="店铺"><el-select v-model="form.stores" multiple style="width:100%"><el-option v-for="s in options.stores" :value="s" :label="s"/></el-select></el-form-item><el-form-item label="站点"><el-select v-model="form.markets" multiple style="width:100%"><el-option v-for="m in options.markets" :value="m" :label="m"/></el-select></el-form-item></el-form><template v-if="true"><TableReset table-key="ListingSyncDialogLists/list-1"/><el-table data-width-key="ListingSyncDialogLists/list-1" @header-dragend="(w:number,_:number,c:any)=>listWidths.resize('list-1',w,c)" @header-contextmenu="(c:any,e:MouseEvent)=>listWidths.resetColumn('list-1',c,e)" :data="jobs" max-height="300"><el-table-column :column-key="'store'" :width="listWidths.width('list-1','store',undefined)" prop="store" label="店铺"/><el-table-column :column-key="'column-2'" :width="listWidths.width('list-1','column-2',undefined)" label="站点"><template #default="{row}">{{row.markets.join(' / ')}}</template></el-table-column><el-table-column :column-key="'column-3'" :width="listWidths.width('list-1','column-3',undefined)" label="状态"><template #default="{row}">{{({queued:'排队中',running:'同步中',succeeded:'已完成',failed:'失败'} as any)[row.status]}}</template></el-table-column><el-table-column :column-key="'column-4'" :width="listWidths.width('list-1','column-4',undefined)" label="进度 / 说明" min-width="250"><template #default="{row}">{{row.error||[row.progress.market,row.progress.saved!=null?'已保存 '+row.progress.saved+' 条':''].filter(Boolean).join(' · ')}}</template></el-table-column></el-table></template><template #footer><el-button @click="emit('close')">关闭</el-button><el-button type="primary" :disabled="!form.stores.length||!form.markets.length" :loading="busy" @click="sync">开始同步</el-button></template></el-dialog></template>
